// 当前军团、真实伤亡与两种专项军令同候选借用；每次读重建上下文，不跨回滚保存子对象地址。
#include "political_field_appointment_integration.hpp"
#include "world_bundle.hpp"
#include "resident/domains/military/military_field_command_rules.hpp"
namespace hanmo::resident { namespace {
// 仅本政治段实际四种记录和S2实际应用能提供历史边界，调用者不能拿任意fact充当过去时刻。
bool boundary(const WorldBundle& w,const StableId& id,Integer tick){const auto* h=w.common.state().facts.find(id);if(!h||h->id!=id)return false;if(h->domain=="politics"){
 if(h->kind==political_field_issue_kind){const auto* r=w.political_field_appointments.authorizations.find(id);return r&&r->id==id&&r->tick==tick;}
 if(h->kind==political_field_accept_kind||h->kind==political_field_decline_kind){const auto* r=w.political_field_appointments.answers.find(id);return r&&r->id==id&&r->accepted==(h->kind==political_field_accept_kind)&&r->tick==tick;}
 if(h->kind==political_field_withdraw_kind){const auto* r=w.political_field_appointments.withdrawals.find(id);return r&&r->id==id&&r->tick==tick;}}
 if(h->domain=="military"&&h->kind=="military_field_command_assigned")for(const auto& r:w.military.field_commands)if(r.id==id)return r.tick==tick;return false;}
// 候选发现只从观察者真实InArmy所属军团向下读取；逐个目标仍由原S2来源和接触口核准。
Outcome<std::vector<MilitaryFieldCommandTarget>> targets(const WorldBundle& w,const StableId& actor){std::vector<MilitaryFieldCommandTarget> result;const auto* person=w.common.actor(actor);const auto* in=person?std::get_if<InArmyLocation>(&person->location):nullptr;if(!in)return {true,std::move(result),{}};const ArmyRecord* army=nullptr;for(const auto& a:w.military.armies)if(a.id==in->army_id)army=&a;if(!army||army->status!="active"||std::find(army->member_actor_ids.begin(),army->member_actor_ids.end(),actor)==army->member_actor_ids.end())return {true,std::move(result),{}};
 unsigned scanned=0;const auto* naval=w.naval_enabled()?&w.naval:nullptr;for(const auto& id:army->unit_ids){if(++scanned>32||result.size()>=64)break;const MilitaryUnitRecord* unit=nullptr;for(const auto& u:w.military.military_units)if(u.id==id)unit=&u;if(!unit||unit->army_id!=army->id)return {false,{},common_failure("MilitaryFieldUnitSourceRequired",id).error};for(const auto kind:{MilitaryFieldCommandKind::unit,MilitaryFieldCommandKind::army}){auto observed=query_military_field_command_source(w.common,w.military,*w.catalog->military,naval,kind,army->id,id);if(!observed.ok)return {false,{},observed.error};const auto& o=observed.value;if(!o.commander_death)continue;std::vector<StableId> people=kind==MilitaryFieldCommandKind::unit?unit->fit:std::vector<StableId>{unit->commander_actor_id};for(const auto& next:people){if(result.size()>=64)break;const auto* who=w.common.actor(next);if(!who||!who->alive||!who->available||who->hp<=0||next==o.commander_actor_id)continue;MilitaryFieldCommandTarget t;t.kind=kind;t.organization_id=o.organization_id;t.army_id=o.army_id;t.campaign_id=o.campaign_id;t.formation_source_id=o.formation_source_id;t.unit_id=id;t.previous_actor_id=o.commander_actor_id;t.next_actor_id=next;t.previous_source=o.command_source;t.predecessor_death=*o.commander_death;t.fleet_id=o.fleet_id;if(kind==MilitaryFieldCommandKind::army){auto captain=query_military_field_command_source(w.common,w.military,*w.catalog->military,naval,MilitaryFieldCommandKind::unit,army->id,id);if(!captain.ok)return {false,{},captain.error};if(captain.value.commander_actor_id!=next)continue;t.candidate_unit_source=captain.value.command_source;}auto contact=query_military_field_contact(w.common,w.military,*w.catalog->military,naval,t,actor);if(!contact.ok){if(contact.error.kind==ErrorKind::rule)continue;return {false,{},contact.error};}auto recipient=query_military_field_contact(w.common,w.military,*w.catalog->military,naval,t,next);if(!recipient.ok){if(recipient.error.kind==ErrorKind::rule)continue;return {false,{},recipient.error};}result.push_back(std::move(t));}}}return {true,std::move(result),{}};}
PoliticalFieldMilitaryRead military_read(const WorldBundle& w){PoliticalFieldMilitaryRead out;
 out.current=[&w](const MilitaryFieldCommandTarget& t){return query_military_field_command_source(w.common,w.military,*w.catalog->military,w.naval_enabled()?&w.naval:nullptr,t.kind,t.army_id,t.unit_id);};
 out.before_fact=[&w](const MilitaryFieldCommandTarget& t,Integer tick,const StableId& id)->Outcome<MilitaryFieldCommandObservation>{if(!boundary(w,id,tick))return {false,{},common_failure("PoliticalFieldHistoryBoundaryRequired",id).error};return query_military_field_command_source_before(w.common,w.military,*w.catalog->military,w.naval_enabled()?&w.naval:nullptr,w.services.military_access(),t.kind,t.army_id,t.unit_id,tick,id);};
 out.contact=[&w](const MilitaryFieldCommandTarget& t,const StableId& actor){return query_military_field_contact(w.common,w.military,*w.catalog->military,w.naval_enabled()?&w.naval:nullptr,t,actor);};
 out.contact_before_fact=[&w](const MilitaryFieldCommandTarget& t,const StableId& actor,Integer tick,const StableId& id)->Outcome<MilitaryFieldCommandContact>{if(!boundary(w,id,tick))return {false,{},common_failure("PoliticalFieldHistoryBoundaryRequired",id).error};return query_military_field_contact_before(w.common,w.military,*w.catalog->military,w.naval_enabled()?&w.naval:nullptr,w.services.military_access(),t,actor,tick,id);};
 out.garrison_site=[&w](const StableId& id)->std::optional<StableId>{for(const auto& g:w.catalog->military->garrisons)if(g.id==id)return g.place_id;return {};};
 out.targets=[&w](const StableId& actor){return targets(w,actor);};
 out.application_preview=[&w](const StableId& actor,const StableId& auth,const StableId& accept){auto r=preview_military_field_command(w.common,w.military,*w.catalog->military,w.services.military_access(),actor,{"field:"+auth,auth,accept});return r.ok?common_success():Status{false,{},r.error};};
 out.application=[&w](const StableId& authorization)->Outcome<std::optional<PoliticalFieldApplicationNotice>>{std::optional<PoliticalFieldApplicationNotice> out;for(const auto& f:w.military.field_commands)if(f.authorization_fact_id==authorization){if(out)return {false,{},common_failure("DuplicateMilitaryFieldApplication").error};out=PoliticalFieldApplicationNotice{f.id,f.authorization_fact_id,f.acceptance_fact_id,f.actor_id,f.tick};}return {true,std::move(out),{}};};return out;
}
struct ReadScope {PoliticalFieldMilitaryRead military;PoliticalFieldAppointmentContext context;explicit ReadScope(const WorldBundle& w):military(military_read(w)),context{w.common,*w.catalog->common,w.organization,*w.catalog->organization,w.local_economy,w.services,*w.catalog->political_field_appointments,w.political_field_appointments,military}{}};
Outcome<std::unique_ptr<ReadScope>> read(const WorldBundle& w){if(!w.political_field_appointments_enabled()||!w.political_field_appointments_seed_complete||!w.political_military_appointments_enabled()||!w.politics_enabled()||!w.catalog->organization||!w.catalog->military||!w.catalog->military->field_command_policy)return {false,{},common_failure("PoliticalFieldProfileRequired").error};return {true,std::make_unique<ReadScope>(w),{}};}
}
Outcome<MilitaryFieldCommandAppointmentProof> PoliticalFieldAppointmentWorldAccess::appointment_for_application(const StableId& auth,const StableId& accept,const StableId& actor)const{auto scope=read(world_);if(!scope.ok)return {false,{},scope.error};return PoliticalFieldAppointmentAccess(scope.value->context).appointment_for_application(auth,accept,actor);}
Outcome<MilitaryFieldCommandAppointmentProof> PoliticalFieldAppointmentWorldAccess::appointment_before_application(const StableId& auth,const StableId& accept,const StableId& fact,Integer tick)const{auto scope=read(world_);if(!scope.ok)return {false,{},scope.error};return PoliticalFieldAppointmentAccess(scope.value->context).appointment_before_application(auth,accept,fact,tick);}
Outcome<std::optional<DecisionProposal>> propose_political_field_appointment_world(const WorldBundle& w,const KnownSubjectView& known,const DirectorPolicy& policy,const DecisionProposal& base){auto scope=read(w);if(!scope.ok)return {false,{},scope.error};return propose_director_field_appointment(scope.value->context,known,policy,base);}
Status validate_political_field_appointment_world(const WorldBundle& w){const bool enabled=w.political_field_appointments_enabled();auto profile=validate_political_field_appointment_layout(enabled,w.catalog->identity.module_versions,w.political_field_appointments_seed_complete?&w.political_field_appointments:nullptr);if(!profile.ok)return profile;if(w.catalog->director){auto d=validate_political_field_director(*w.catalog->director,w.director,w.catalog->political_field_appointments.get(),enabled?&w.political_field_appointments:nullptr);if(!d.ok)return d;}auto history=validate_political_field_appointment_command_history(w.common,enabled);if(!history.ok)return history;if(!enabled)return w.political_field_appointments.authorizations.empty()&&w.political_field_appointments.answers.empty()&&w.political_field_appointments.withdrawals.empty()?common_success():common_failure("UnexpectedPoliticalFieldState");auto scope=read(w);if(!scope.ok)return {false,{},scope.error};auto valid=validate_political_field_appointments(scope.value->context);if(!valid.ok)return valid;valid=validate_political_field_appointment_receipts(scope.value->context,[](const CommitResult& r){return r.details&&std::holds_alternative<Done>(r.details->data);});if(!valid.ok)return valid;return validate_military_field_commands(w.common,w.military,*w.catalog->military,w.services.military_access());}
Outcome<PoliticalFieldAppointmentQuote> prepare_political_field_appointment_world(const WorldBundle& w,const StableId& actor,const PoliticalFieldAppointmentCommand& command){auto scope=read(w);if(!scope.ok)return {false,{},scope.error};return preview_political_field_appointment(scope.value->context,actor,command);}
Outcome<StableId> commit_political_field_appointment_world(WorldBundle& w,const StableId& actor,const PoliticalFieldAppointmentCommand& command,const PoliticalFieldAppointmentQuote& quote){auto scope=read(w);if(!scope.ok)return {false,{},scope.error};return apply_political_field_appointment_in_transaction(w.common,w.political_field_appointments,scope.value->context,actor,command,quote);}
Outcome<BoundaryValue> query_political_field_appointment_world(const WorldBundle& w,Integer cursor){auto scope=read(w);if(!scope.ok)return {false,{},scope.error};return query_political_field_appointments(scope.value->context,cursor);}
}
